// Leah's handwritten journals: scanned pages paired with their transcriptions.
// Generated by scripts/build_journals.py from scripts/journals.config.json.

import journalsData from './journals.json';

export interface JournalImage {
  image: string;
  width: number;
  height: number;
}

export interface JournalPage extends JournalImage {
  /** Transcribed text that appears on this scanned page, in order. */
  transcription: { page: string; text: string }[];
}

export interface Journal {
  id: string;
  title: string;
  date: string | null;
  cover: JournalImage;
  pages: JournalPage[];
}

export const JOURNALS = journalsData as Journal[];

export const JOURNAL_VIDEO = {
  src: '/video/leah-reads-her-journal.mp4',
  poster: '/video/leah-reads-her-journal.jpg',
  width: 640,
  height: 480,
};

export function getJournal(id: string | undefined): Journal | undefined {
  return JOURNALS.find((j) => j.id === id);
}
